window.GRIM_PARTS["details-81"]=[{"id":"q0014","name":"急救","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a765e09971577.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"如果你每次受伤都要死一次，那就走不了多远。制作几根绷带。你需要一些亚麻和布料。也许你可以复活，但如果在战斗中活不下去，那又有什么意义？"},{"title":"任务目标","rows":[{"label":"制作绷带","value":6}]},{"title":"完成奖励","rows":[{"label":"线","value":"× 15"},{"label":"苦药酒","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0259","i0039"],"english":"First Aid"},{"id":"q0015","name":"悲伤的夜晚","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/ae20cc8c62d86.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你的北边有一个墓地。那里之前并不是特别平静，但最近据说晚上有人在那边恸哭。我知道那边是什么情况，但你还是要去查看一番。"},{"title":"任务目标","rows":[{"label":"找到恸哭的人","value":1}]},{"title":"完成奖励","rows":[{"label":"1级召唤不死者卷轴","value":"× 3"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0007"],"english":"Night of Sorrow"},{"id":"q0016","name":"林中小屋","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a2f0f50cd3537.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"一名与反叛骑士团有牵连的祭司住在附近的一间小屋。遗憾的是，我们不知道它的确切地点。要找到这个异教徒的住所，你必须追踪地图。跟着渡鸦走，它们会把你带到正确的地方。"},{"title":"任务目标","rows":[{"label":"解锁看守者地点","value":1}]},{"title":"完成奖励","rows":[{"label":"弯刀","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0698"],"english":"Hut in the Forest"},{"id":"q0017","name":"造访邻居","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a2e92d134602e.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你必须干掉看守者。他不太愿意交际，并会试图杀死你。让他知道这是个错误。我必须检验我的理论，而且你可以获得他的东西。但要注意：祭司是一个强大的战士，而且瘟疫动物会听从他的指挥。"},{"title":"任务目标","rows":[{"label":"击杀看守者","value":1}]},{"title":"完成奖励","rows":[{"label":"青铜锁子甲","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i1013"],"english":"Visiting a Neighbor"},{"id":"q0018","name":"不在地图上","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/aaa98ac93ad71.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我是对的：他的性质和你一样。他不会永久死亡，而是每天都会复活。据说有人看到他带着一张地图。夺得它。不断尝试直到交好运。你做这件事的时候会得到更好的装备，它们会派上用场。"},{"title":"任务目标","rows":[{"label":"解锁被弃者地下城地点","value":1}]},{"title":"完成奖励","rows":[{"label":"皮包","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0860"],"english":"Uncharted"},{"id":"q0019","name":"过往的遗迹","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a4fb67036388f.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"时间可以改变一切。据说被弃骑士团占据了一座古城堡的拱形大厅，并把那里当成了据点。想找到真相并不容易：地下城的门只能用钥匙打开。不过，下面的战利品能让你用好一阵子了。有空就去那儿看看吧。"},{"title":"任务目标","rows":[{"label":"前往被弃者地下城废墟","value":1}]},{"title":"完成奖励","rows":[{"label":"铜锭","value":"× 20"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0229"],"english":"Ruins of the Past"},{"id":"q0020","name":"深入过去","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a43687bddf2ba.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"在异教徒的住所，你应该会找到一把钥匙。他被称为看守者是有原因的。这把钥匙可以打开被弃者地下城。反叛的战士在里面等着你，他们对你的力量和机智是极大的挑战。想想他们所守护的秘密吧......"},{"title":"任务目标","rows":[{"label":"使用钥匙进入被弃者地下城","value":1}]},{"title":"完成奖励","rows":[{"label":"青铜宝箱","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i1095"],"english":"Deep into the Past"},{"id":"q0021","name":"盛宴","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/aabd241efb0d3.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我对你的前生一无所知。也许你是个富二代，或者只是铁匠的学徒。既然那辈子已经过去，这些也毫无意义，不是吗？你现在是流亡者，你在学习如何在新世界活下去。这里充满了各种机会，虽然看上去并非如此。我会用最简单、也是最重要的例子证明给你看 – 食物！"},{"title":"任务目标","rows":[{"label":"准备韭葱汤","value":5},{"label":"准备浆果饮料","value":5},{"label":"准备牛肉干","value":5}]},{"title":"完成奖励","rows":[{"label":"麦芽酒","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0070"],"english":"A Feast for Dinner"},{"id":"q0022","name":"选择盟友","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"众所周知，三股更高等的力量在冥冥之中影响着瘟疫之地。小心了，很快你就会收到自他们使者的信函。然而，每个使者都不知道其他两位使者也跟你取得了联系。按这些使者所要求的去做吧，去赢取强大守护者的青睐。切记，你只能接受一位守护者之力。当你做出抉择，其余两位将会视你为叛徒。"},{"title":"任务目标","rows":[{"label":"阅读友人寄来的警告信","value":1}]}],"related":[],"english":"Choosing Allies"},{"id":"q0023","name":"赫拉特教会的恩赐","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"","stats":[{"label":"委托人","value":"赫拉特教会的使者"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你有福了！赫拉特之光将被荣耀的赐福予你。这光将是英勇战士手中刺穿黑暗与灰色死神的利刃。按这光的意志行事，证明你的虔诚，释放你内在的力量吧！夜游神把它们的宝藏藏在罪恶的秘密地窖里。找到它们的夜间地窖，赫拉特之光将会与你同在。\n\n夜晚地窖可在夜间的3个骷髅地点找到。"},{"title":"任务目标","rows":[{"label":"搜查1个夜间地窖","value":1}]}],"related":[],"english":"Harat's Gifts"},{"id":"q0024","name":"瘟疫之神的恩赐","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"","stats":[{"label":"委托人","value":"瘟疫之神的使者"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"接受瘟疫之神恩赐的时刻到来了。他灰色死神的力量将会改变你，给你予打败你敌人的力量。你必须向瘟疫之神证明你的虔诚以获取他的青睐 - 按他的意志行事吧！流亡者不受瘟疫之神的影响。杀了他们，夺走他们的力量，我们就会赏赐予你。"},{"title":"任务目标","rows":[{"label":"杀死3个流亡者","value":3}]}],"related":[],"english":"The Plague God's Gifts"},{"id":"q0025","name":"无名之神的恩赐","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"","stats":[{"label":"委托人","value":"无名之神的使者"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"洗净你的意识，接受无名之神的恩赐吧！死亡将会带走所有人。向无名之神证明你的虔诚，按他的意志行事，释放你内在的力量。瘟疫之神创造的畸形之物破坏了自然的秩序。去吧，去杀死那些叫做被咒骑士的喽啰，杀死那本属于死亡的一切。"},{"title":"任务目标","rows":[{"label":"杀死5个被咒骑士","value":5}]}],"related":[],"english":"The Nameless God's Gifts"},{"id":"q0026","name":"卡牌游戏","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a95c2858662df.webp","stats":[{"label":"委托人","value":"狡猾吝啬鬼"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"有个好旅伴，路上的时间就会过得飞快！和我打一局牌怎么样？为了一场好牌，我愿意赌上我的任何宝物，甚至这只非凡的恐狼！我的大车很容易找到。我会在你的行省地图上把它标出来！"},{"title":"任务目标","rows":[{"label":"与狡猾吝啬鬼玩牌","value":1}]},{"title":"完成奖励","rows":[{"label":"活力药水","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0033"],"english":"Card Game"},{"id":"q0027","name":"组合牌","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/ada67aa456452.webp","stats":[{"label":"委托人","value":"狡猾吝啬鬼"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"在这个游戏中，你需要组成组合。每一手组合牌都各有其名称和奖励。试着组成民兵组合牌，也就是两个对子。你只需要一点耐心和信心。"},{"title":"任务目标","rows":[{"label":"制作民兵组合牌","value":1}]},{"title":"完成奖励","rows":[{"label":"流星锤","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0706"],"english":"Card Hand"},{"id":"q0028","name":"试试手气","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a9052ab79c083.webp","stats":[{"label":"委托人","value":"狡猾吝啬鬼"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我喜欢打牌。你要是能证明你也喜欢，我就把我的特別宝贝和我的秘密都告诉你。"},{"title":"任务目标","rows":[{"label":"打牌20次","value":20}]},{"title":"完成奖励","rows":[{"label":"铁钉盾","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0821"],"english":"Test your luck"},{"id":"q0029","name":"找好友","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a2f0f50cd3537.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"在瘟疫之地独自生存是很困难的。你应该寻求其他流亡者的帮助。至少将一位流亡者添加为好友。要了解如何邀请好友，请离开你的地点并选择左下角的骑士图标。稍后我会向你展示如何在好友的帮助下获得奖励。"},{"title":"任务目标","rows":[{"label":"向好友列表中添加好友","value":1}]},{"title":"完成奖励","rows":[{"label":"弯刀","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0698"],"english":"Find Friends"},{"id":"q0030","name":"流亡者宝箱","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a01f245dfa180.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"在好友选项卡中打开流亡者宝箱。你必须拥有5把流亡者钥匙才能这样做。尝试与5个好友达成协议来交换钥匙。这是免费的，你可以在宝箱中找到很多有用的物品！"},{"title":"任务目标","rows":[{"label":"打开流亡者、骑士或贵族宝箱","value":1}]},{"title":"完成奖励","rows":[{"label":"变种剑","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0689"],"english":"Exile's Chest"},{"id":"q0031","name":"骑士宝箱","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a5e6e9c133907.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"在好友选项卡中打开骑士宝箱。该宝箱拥有更棒的奖励，但需要相同数量的好友。给好友提供有用的建议，他们很快就会达到50级，然后他们便会给你所需的钥匙。"},{"title":"任务目标","rows":[{"label":"打开骑士或贵族宝箱","value":1}]},{"title":"完成奖励","rows":[{"label":"双刃大砍刀","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0668"],"english":"Knight's Chest"},{"id":"q0032","name":"贵族宝箱","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a0a314a151435.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"在好友选项卡中打开贵族宝箱。你已经知道该怎么做了。"},{"title":"任务目标","rows":[{"label":"打开贵族宝箱","value":1}]},{"title":"完成奖励","rows":[{"label":"戟","value":"× 1"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0662"],"english":"Aristocrat's Chest"},{"id":"q0033","name":"最终避难处","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/ac1fec21280b0.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你不认识我，但我们已经见过面了。我叫塞巴斯蒂安·科尔，是红天使骑士团的指挥官。是我下令让鲁伯特护送你离开城市。当鲁伯特没有回来报信时，我以为你们俩都已经死了。很高兴我的判断错了。我的小队在你的避难所附近安营扎寨。我们向所有需要帮助的人提供帮助。即使你不需要我们的帮助，也请过来与我们一起为死去的人祈祷吧。"},{"title":"任务目标","rows":[{"label":"轻触赫拉特雕像","value":1}]},{"title":"完成奖励","rows":[{"label":"铜陷阱","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0160"],"english":"Final Resting Place"},{"id":"q0034","name":"深藏地下","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a0fdbd0302a00.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你已经知道，瘟疫之地充斥着各种各样的生物。其中最危险的是绝望的灵魂，它们愿意为了自己的利益而攻击他人。你的城堡是你坚守的堡垒，但藏身之处再安全也不为过，对吗？建一个地下室。你可以把所有的贵重物品存放在那里，无需担心强盗。而且，这还能让你的城堡有更多空间。"},{"title":"任务目标","rows":[{"label":"建造一个地下室","value":1}]},{"title":"完成奖励","rows":[{"label":"U形钉","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0244"],"english":"Bowels of the Earth"},{"id":"q0035","name":"大型开发","category":"quests","subcategory":"第 I 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a0fdbd0302a00.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 I 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"地上挖出的洞是个良好的开端。你已经有了遇到危险时的避难所。试着多挖一些土。没错，这需要艰苦的工作和资源，但你的回报将是一个宽敞的藏身处。不要忘了加固墙壁，你总不希望城堡在你上方坍塌，对吧？"},{"title":"任务目标","rows":[{"label":"清理地下室的一部分","value":1}]},{"title":"完成奖励","rows":[{"label":"U形钉","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0244"],"english":"Extensive Development"},{"id":"q0036","name":"伟大瘟疫","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a989af9e3cf47.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你现在已经知道了，灰色死神并非普通的传染病。它源自更高等的力量，即尘世间被尊为瘟疫之神的存在。但不要愚蠢地只凭自己所见来评判他的行为。你们命运之间的羁绊比你想象得还要深。附近一座废弃的图书馆，去那里寻找瘟疫起源的线索吧。我希望你在那里找到的东西，可以帮你更好地理解我的话。"},{"title":"任务目标","rows":[{"label":"阅读关于瘟疫起源的卷轴","value":5}]},{"title":"完成奖励","rows":[{"label":"灵魂碎片","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0260"],"english":"Great Plague"},{"id":"q0037","name":"手工锻造","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/af92c324b5d00.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"没错，冷酷国王即将回归，届时他将绝不留情。所以我需要你的帮助。我们必须借助所有可以召集的力量，才能安然度过死亡之夜。为了实现那个目标，我们必须继续你的教育。尝试锻造一把小匕首。人们经常因它的尺寸而忽视它的存在，但注意到的时候却已太晚了。"},{"title":"任务目标","rows":[{"label":"熔化铜锭","value":10},{"label":"制作匕首","value":1}]},{"title":"完成奖励","rows":[{"label":"松木板","value":"× 20"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0224"],"english":"Blacksmithing"},{"id":"q0038","name":"格斗俱乐部","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/ad25aed43fe0c.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你已经知道，这片大陆还有其他流亡者的存在。他们中的许多人只凭自己喜好行事，因此可能会无缘无故攻击你。不过有些人或许可以帮你更好地认识这个世界。我听说流亡者有时候会举行殊死格斗。我会把比赛组织者的住所在地图上标出来。不打赢就别回来。"},{"title":"任务目标","rows":[{"label":"了解关于锦标赛的更多信息","value":1}]},{"title":"完成奖励","rows":[{"label":"潜行药水","value":"× 2"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0048"],"english":"Fight Club"},{"id":"q0039","name":"杀人犯","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a353aeb3cf1e5.webp","stats":[{"label":"委托人","value":"马雷·撒图克"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"进入锦标赛通常没那么简单。但你在我们的格斗中证明了自己的实力，所以我给你破个例。格斗必须在双方同意的情况下开始。我们也许会分生死，但我们尊重彼此。我们不是杀人犯，不允许从背后偷袭。如果你被别人偷袭，那就给他们点教训，让他们知道攻击你不是个好主意。等你先料理了几个这样的无耻之徒，再来找我。"},{"title":"任务目标","rows":[{"label":"击杀其他流亡者","value":2}]},{"title":"完成奖励","rows":[{"label":"青铜钉","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0230"],"english":"Murderers"},{"id":"q0040","name":"死斗竞技场","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a8313dd7cbaf7.webp","stats":[{"label":"委托人","value":"马雷·撒图克"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"面子是自己挣得。好了，现在你可以加入锦标赛了。你随后要参加三场比赛。战胜每一位对手后，你就可以成为死斗竞技场的冠军，并收到一份奖励。我给你送去了一张标有营地坐标的地图。带上你最好的装备，后面的战斗将非常惨烈。"},{"title":"任务目标","rows":[{"label":"成为竞技场冠军","value":1}]},{"title":"完成奖励","rows":[{"label":"厚布","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0234"],"english":"Arena of the Dead"},{"id":"q0041","name":"恶人无休","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a198980038d3b.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"有没有想过为什么你总是在家附近复活？在死亡后，你的灵魂总是被吸引到第一次死亡的地点。你将和它永远紧密相连。既然以后这里就是你永远的家了，也许你应该把它装饰点好一点。不如先造张席子吧，这比睡在地板上舒服多了。"},{"title":"任务目标","rows":[{"label":"摆放席子","value":1}]},{"title":"完成奖励","rows":[{"label":"皮条","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0236"],"english":"No Rest for the Wicked"},{"id":"q0042","name":"栅栏","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/aa70df0610f83.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"现在要设法保护你的家，阻止不速之客。试着制作几根木签，然后把它们插在家的周围。这可以避免你的贵重物品丢失。"},{"title":"任务目标","rows":[{"label":"制作木签","value":20}]},{"title":"完成奖励","rows":[{"label":"流亡者的公告","value":"× 3"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0017"],"english":"The Palisade"},{"id":"q0043","name":"厚墙","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a49fafe390592.webp","stats":[{"label":"委托人","value":"您的朋友"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"你的家是最重要的守护场所。加固围墙并建造新的设备。在装备更好的城堡中，你可以更快烹饪肉食或打理多个花园苗床。"},{"title":"任务目标","rows":[{"label":"将城堡升到第 5 级","value":1}]},{"title":"完成奖励","rows":[{"label":"青铜锭","value":"× 7"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0228"],"english":"Strong Walls"},{"id":"q0044","name":"血海深仇","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a13913b5ace85.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"我已经了解了你接触的那位\"好友\"了。他们并非你认为的好友。"},{"title":"任务目标","rows":[{"label":"查看罗恩爵士的命令","value":1}]},{"title":"完成奖励","rows":[{"label":"烈酒","value":"× 5"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0231"],"english":"Blood Feud"},{"id":"q0045","name":"第二层皮","category":"quests","subcategory":"第 II 幕","summary":"查看来信、任务目标与完成奖励。","image":"assets/images/a46868060dac9.webp","stats":[{"label":"委托人","value":"塞巴斯蒂安·科尔"},{"label":"章节","value":"第 II 幕"}],"sections":[{"title":"任务来信 · 含剧情","text":"虽然福金打算利用你，但却把你准备得不错。在对抗四周的混沌力量时，知识是我们最大的优势。我会从这里接管你的教育。首先，你需要缝制一件皮甲。虽然它抵挡不了刀剑突刺，但对于劈砍还是有一定防御能力的。"},{"title":"任务目标","rows":[{"label":"制作软铠甲","value":1},{"label":"制作棉裤","value":1},{"label":"制作皮靴","value":1}]},{"title":"完成奖励","rows":[{"label":"石块","value":"× 10"}]},{"title":"图鉴说明","text":"封面为任务奖励物品图标。"}],"related":["i0237"],"english":"Second Skin"}];
